import{_ as s,o as i,c as a,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Versioning & Release Policy","description":"","frontmatter":{},"headers":[],"relativePath":"en/21-versioning-and-release-policy.md","filePath":"en/21-versioning-and-release-policy.md"}'),t={name:"en/21-versioning-and-release-policy.md"};function o(l,e,r,p,c,d){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="versioning-release-policy" tabindex="-1">Versioning &amp; Release Policy <a class="header-anchor" href="#versioning-release-policy" aria-label="Permalink to &quot;Versioning &amp; Release Policy&quot;">​</a></h1><blockquote><p><strong>SemVer Governance, Lifecycle Management, and Releases in SoftForge</strong><br><em>Semantic Versioning 2.0.0 • Rolling Main • Single Monorepo Version • Continuous CHANGELOG</em></p></blockquote><hr><h2 id="_1-overview-and-philosophy" tabindex="-1">1. Overview and Philosophy <a class="header-anchor" href="#_1-overview-and-philosophy" aria-label="Permalink to &quot;1. Overview and Philosophy&quot;">​</a></h2><p><strong>SoftForge</strong> is built for both human engineers and <strong>Autonomous AI Agents</strong> constructing production-grade applications.</p><p>To balance rapid continuous innovation with operational predictability, we implement the <strong>Hybrid SemVer</strong> model:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Main[&quot;Branch main&lt;br/&gt;(Continuous Rolling Release)&quot;] --&gt;|Verify Validation| CI[&quot;100% Guardrails Pass&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CI --&gt;|release.py| Tag[&quot;Formal Releases&lt;br/&gt;(v1.0.0, v1.1.0, v2.0.0)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Tag --&gt;|Syncs| Changelog[&quot;CHANGELOG.md&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Tag --&gt;|Distributes| Downstream[&quot;Downstream Apps &amp; Projects&quot;]</span></span></code></pre></div><ol><li><strong><code>main</code> Branch (Continuous Rolling Release):</strong><br> The primary branch is always in a deployable, green state. Every commit passes 100% of static types, linters, and integration tests via <code>verify.py</code>.</li><li><strong>Formal SemVer Releases (<code>vX.Y.Z</code>):</strong><br> Milestones frozen in time with annotated Git tags, accompanied by comprehensive notes in <code>CHANGELOG.md</code> and GitHub Releases.</li><li><strong>Single Global Version (Monorepo):</strong><br> The Backend API (<code>apps/api</code>), Frontend (<code>apps/web</code>), Themes (<code>themes/</code>), AI Skills, and Documentation advance in unison under the exact same version number.</li></ol><hr><h2 id="_2-semver-2-0-0-structure-major-minor-patch" tabindex="-1">2. SemVer 2.0.0 Structure (<code>MAJOR.MINOR.PATCH</code>) <a class="header-anchor" href="#_2-semver-2-0-0-structure-major-minor-patch" aria-label="Permalink to &quot;2. SemVer 2.0.0 Structure (\`MAJOR.MINOR.PATCH\`)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       v 1 . 2 . 4</span></span>
<span class="line"><span>         │   │   │</span></span>
<span class="line"><span>         │   │   └── PATCH: Bug fixes, security patches, docs (no API changes)</span></span>
<span class="line"><span>         │   └────── MINOR: New vertical slices, new themes, backwards-compatible routes</span></span>
<span class="line"><span>         └────────── MAJOR: Breaking contract changes, route removals, destructive migrations</span></span></code></pre></div><h3 id="_1-major-vx-0-0" tabindex="-1">1. MAJOR (<code>vX.0.0</code>) <a class="header-anchor" href="#_1-major-vx-0-0" aria-label="Permalink to &quot;1. MAJOR (\`vX.0.0\`)&quot;">​</a></h3><ul><li><strong>When it applies:</strong> Any modification breaking compatibility with existing contracts.</li><li><strong>Examples in SoftForge:</strong><ul><li>Removing or altering fields in OpenAPI schemas without backwards compatibility.</li><li>Destructive database alterations (dropping or renaming columns/tables).</li><li>Breaking changes to the <code>softforge-theme.json</code> specification or <code>--sf-*</code> CSS variables.</li></ul></li><li><strong>Transition Policy:</strong> Landed directly in MAJOR with: <ol><li>Reversible Alembic migrations.</li><li>Step-by-step upgrade guide documented in <code>CHANGELOG.md</code>.</li></ol></li></ul><h3 id="_2-minor-v1-x-0" tabindex="-1">2. MINOR (<code>v1.X.0</code>) <a class="header-anchor" href="#_2-minor-v1-x-0" aria-label="Permalink to &quot;2. MINOR (\`v1.X.0\`)&quot;">​</a></h3><ul><li><strong>When it applies:</strong> New features and vertical slices added in a 100% backwards-compatible manner.</li><li><strong>Examples in SoftForge:</strong><ul><li>Adding a new vertical slice to <code>apps/api/src/slices/</code> (e.g., <code>billing</code>, <code>storage</code>).</li><li>Adding new HTTP endpoints or optional schema fields.</li><li>Additive database migrations (new tables or columns with default values).</li><li>Adding new themes to <code>themes/</code>.</li><li>Adding new skills to <code>.agents/skills/</code>.</li></ul></li></ul><h3 id="_3-patch-v1-0-x" tabindex="-1">3. PATCH (<code>v1.0.X</code>) <a class="header-anchor" href="#_3-patch-v1-0-x" aria-label="Permalink to &quot;3. PATCH (\`v1.0.X\`)&quot;">​</a></h3><ul><li><strong>When it applies:</strong> Bug fixes, security patches, documentation, and internal optimizations.</li><li><strong>Examples in SoftForge:</strong><ul><li>Fixing an edge case in <code>service.py</code>.</li><li>UI fixes or responsiveness adjustments in <code>apps/web</code>.</li><li>Dependency upgrades resolving CVEs.</li><li>Fixing typos and links in <code>docs/</code>.</li></ul></li></ul><hr><h2 id="_3-release-automation-with-release-py" tabindex="-1">3. Release Automation with <code>release.py</code> <a class="header-anchor" href="#_3-release-automation-with-release-py" aria-label="Permalink to &quot;3. Release Automation with \`release.py\`&quot;">​</a></h2><p>SoftForge includes a dedicated CLI release utility:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run guardrails, sync manifests, generate changelog, and create Git tag:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/release.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bump</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Add team invites vertical slice&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or specify an explicit target version:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/release.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Official GA Release&quot;</span></span></code></pre></div><h3 id="script-execution-sequence" tabindex="-1">Script Execution Sequence: <a class="header-anchor" href="#script-execution-sequence" aria-label="Permalink to &quot;Script Execution Sequence:&quot;">​</a></h3><ol><li><strong>Guardrails Gate:</strong> Executes <code>python tools/scripts/verify.py</code>. If any check fails, the release halts immediately.</li><li><strong>Version Synchronization:</strong> Updates <code>apps/api/pyproject.toml</code>, <code>apps/web/package.json</code>, and <code>docs/package.json</code>.</li><li><strong>Changelog Generation:</strong> Inspects recent Conventional Commits and prepends the new version block to <code>CHANGELOG.md</code>.</li><li><strong>Git Commit and Tag:</strong> Commits with <code>chore(release): release vX.Y.Z</code> and tags <code>vX.Y.Z</code>.</li></ol><hr><h2 id="_4-keeping-downstream-projects-up-to-date" tabindex="-1">4. Keeping Downstream Projects Up to Date <a class="header-anchor" href="#_4-keeping-downstream-projects-up-to-date" aria-label="Permalink to &quot;4. Keeping Downstream Projects Up to Date&quot;">​</a></h2><p>To keep applications created with SoftForge synced with upstream improvements:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add upstream repository:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/omauriciofala/softforge.redepronta.com.git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Fetch latest releases and tags:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Merge a specific stable release:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.1.0</span></span></code></pre></div><p>Apply any new database migrations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/migrate.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/verify.py</span></span></code></pre></div>`,29)])])}const k=s(t,[["render",o]]);export{g as __pageData,k as default};
